"rules": [
{
"id": "r1",
"text": "If a bar chart's printed percentage labels are treated as the authoritative values for each product's market share, and the task's goal of selecting a primary compatibility target is interpreted as choosing the product with the largest market share, then the product with the highest printed percentage is the supported option.",
"component": "encoding/task relation",
"conditions": "Assumes printed labels are correct and that 'primary compatibility target' maps to maximum market share."
},
{
"id": "r2",
"text": "If the visual heights of the bars are treated as the authoritative representation of market share, ignoring the printed percentage labels, and the task's goal is interpreted as choosing the product with the largest market share, then the product with the tallest bar is the supported option.",
"component": "encoding/task relation",
"conditions": "Assumes bar geometry is correct and that 'primary compatibility target' maps to maximum market share."
},
{
"id": "r3",
"text": "If the task's goal of selecting a primary compatibility target is not explicitly defined by a specific metric (e.g., market share, growth rate, or strategic importance) in the public instructions, then the chart alone is insufficient to determine a single correct option, making the choice underdetermined.",
"component": "task relation",
"conditions": "Assumes no hidden policy or external context defines the selection criteria beyond the visible text."
}
],
